19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", source = "owner", qualifiedByName = "toDisplayName")
23	    @Mapping(target = "initials", source = "owner", qualifiedByName = "toInitials")
24	    @Mapping(target = "membershipNumber", source = "owner", qualifiedByName = "toMembershipNumber")
25	    @Mapping(target = "membershipTier", source = "owner", qualifiedByName = "toMembershipTier")
26	    @Mapping(target = "locality", source = "owner", qualifiedByName = "toLocality")
27	    OwnerDto toOwnerDto(Owner owner);
28	
29	    /**
30	     * Fixed city-to-region table used to derive an owner's locality.
31	     */
32	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
33	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
34	
35	    /**
36	     * Derives the owner's locality as the canonical region for the owner's city from the fixed
37	     * city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}),
38	     * or {@code 'UNKNOWN'} when the city is not in the table.
39	     */
40	    @Named("toLocality")
41	    default String toLocality(Owner owner) {
42	        if (owner == null) {
43	            return null;
44	        }
45	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
46	    }
47	
48	    /**
49	     * Formats the owner's stored names as {@code 'LastName, FirstName'}.
50	     */
51	    @Named("toDisplayName")
52	    default String toDisplayName(Owner owner) {
53	        if (owner == null) {
54	            return null;
55	        }
56	        return owner.getLastName() + ", " + owner.getFirstName();
57	    }
58	
59	    /**
60	     * Returns the owner's initials as the upper-cased first letters of firstName and lastName,
61	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
62	     */
63	    @Named("toInitials")
64	    default String toInitials(Owner owner) {
65	        if (owner == null) {
66	            return null;
67	        }
68	        return initial(owner.getFirstName()) + initial(owner.getLastName());
69	    }
70	
71	    /**
72	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}, where {@code YY} is
73	     * the last two digits of the {@code registrationDate} year, e.g. {@code 'SYD-SMI-0007-M26'}. Returns
74	     * {@code null} when either the customer code or the registration date is absent.
75	     */
76	    @Named("toMembershipNumber")
77	    default String toMembershipNumber(Owner owner) {
78	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
79	            return null;
80	        }
81	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
82	    }
83	
84	    /**
85	     * Returns the owner's membership tier: {@code 'SILVER'} when the owner has no namesakes
86	     * ({@code namesakeCount} is 0) and a non-blank email is present, otherwise {@code 'BRONZE'}.
87	     */
88	    @Named("toMembershipTier")
89	    default String toMembershipTier(Owner owner) {
90	        if (owner == null) {
91	            return null;
92	        }
93	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
94	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
95	        return noNamesakes && hasEmail ? "SILVER" : "BRONZE";
96	    }
97	
98	    private static String initial(String name) {
99	        if (name == null || name.isEmpty()) {
100	            return "";
101	        }
102	        return Character.toUpperCase(name.charAt(0)) + ".";
103	    }
104	
105	    Owner toOwner(OwnerDto ownerDto);
106	
107	    @Mapping(target = "id", ignore = true)
108	    @Mapping(target = "pets", ignore = true)
109	    Owner toOwner(OwnerFieldsDto ownerDto);
110	
111	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
112	
113	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
114	
115	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
116	        OwnerPageDto ownerPageDto = new OwnerPageDto();
117	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
118	        ownerPageDto.setPage(ownerPage.getNumber());
119	        ownerPageDto.setSize(ownerPage.getSize());
120	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
121	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
122	        return ownerPageDto;
123	    }
124	}
