490	     *
491	     * @param lastName the incoming owner's last name (already validated non-blank)
492	     * @param address the incoming owner's address (already validated non-blank)
493	     * @throws DuplicateHouseholdException if another owner already has this last name and address
494	     */
495	    private void requireUniqueHousehold(String lastName, String address) {
496	        String normalizedLastName = normalizeForHousehold(lastName);
497	        String normalizedAddress = householdAddressKey(address);
498	        boolean taken = this.clinicService.findAllOwners().stream()
499	            .anyMatch(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
500	                && householdAddressKey(existing.getAddress()).equals(normalizedAddress));
501	        if (taken) {
502	            throw new DuplicateHouseholdException(lastName, address);
503	        }
504	    }
505	
506	    /**
507	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
508	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
509	     * comparisons are case-insensitive.
510	     */
511	    private static String normalizeForHousehold(String value) {
512	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
513	    }
514	
515	    /**
516	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
517	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
518	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
519	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
520	     * value normalizes to the empty string, so the required-field check rejects an address that is
521	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
522	     *
523	     * @param address the raw address value from the request (may be {@code null})
524	     * @return the normalized address, or the empty string when blank after normalization
525	     */
526	    private static String normalizeAddress(String address) {
527	        if (address == null) {
528	            return "";
529	        }
530	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
531	        if (collapsed.isEmpty()) {
532	            return "";
533	        }
534	        String[] tokens = collapsed.split(" ");
535	        StringBuilder sb = new StringBuilder();
536	        for (String token : tokens) {
537	            String expanded = switch (token) {
538	                case "ST" -> "STREET";
539	                case "RD" -> "ROAD";
540	                case "AVE" -> "AVENUE";
541	                default -> token;
542	            };
543	            if (sb.length() > 0) {
544	                sb.append(' ');
545	            }
546	            sb.append(expanded);
547	        }
548	        return sb.toString();
549	    }
550	
551	    /**
552	     * Derives the comparison key for an address used by household-duplicate detection and the shared
553	     * household identifier: the address is first put in its canonical normalized form and then
554	     * lower-cased and whitespace-collapsed, so every comparison and the derived id agree on the
555	     * normalized address regardless of the raw casing, spacing or abbreviations supplied.
556	     */
557	    private static String householdAddressKey(String address) {
558	        return normalizeForHousehold(normalizeAddress(address));
559	    }
560	
561	    /**
562	     * Joins the household identified by this last name and address, returning the stable shared
563	     * {@code householdId} to store on the joining owner. The identifier is derived deterministically
564	     * from the normalized last name and address, so every owner in the same household resolves to the
565	     * same value. Any existing household members that predate this feature (or were created without
566	     * opting in) are back-filled with the shared identifier so the whole household agrees.
567	     *
568	     * @param lastName the joining owner's last name (already validated non-blank)
569	     * @param address the joining owner's address (already validated non-blank)
570	     * @return the shared household identifier for this last name and address
571	     */
572	    private String joinHousehold(String lastName, String address) {
573	        String normalizedLastName = normalizeForHousehold(lastName);
574	        String normalizedAddress = householdAddressKey(address);
575	        String householdId = householdIdFor(normalizedLastName, normalizedAddress);
576	        this.clinicService.findAllOwners().stream()
577	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
578	                && householdAddressKey(existing.getAddress()).equals(normalizedAddress))
579	            .filter(existing -> !householdId.equals(existing.getHouseholdId()))
580	            .forEach(existing -> {
581	                existing.setHouseholdId(householdId);
582	                this.clinicService.saveOwner(existing);
583	            });
584	        return householdId;
585	    }
586	
587	    /**
588	     * Derives a stable household identifier from the already-normalized last name and address as the
589	     * upper-cased first 12 hex characters of their SHA-256 digest. Deterministic so the same household
590	     * always maps to the same identifier.
591	     */
592	    private static String householdIdFor(String normalizedLastName, String normalizedAddress) {
593	        try {
594	            byte[] digest = MessageDigest.getInstance("SHA-256")
595	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
596	            StringBuilder sb = new StringBuilder();
597	            for (byte b : digest) {
598	                sb.append(String.format("%02X", b));
599	            }
600	            return sb.substring(0, 12);
601	        }
602	        catch (NoSuchAlgorithmException e) {
603	            throw new IllegalStateException("SHA-256 not available", e);
604	        }
605	    }
606	}
