128	    @Override
129	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
130	        List<String> missingFields = new ArrayList<>();
131	        requireNonBlank(missingFields, "firstName", ownerFieldsDto.getFirstName());
132	        requireNonBlank(missingFields, "lastName", ownerFieldsDto.getLastName());
133	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
134	        requireNonBlank(missingFields, "address", normalizedAddress);
135	        requireNonBlank(missingFields, "city", ownerFieldsDto.getCity());
136	        requireNonBlank(missingFields, "telephone", ownerFieldsDto.getTelephone());
137	        if (!missingFields.isEmpty()) {
138	            throw new MissingRequiredFieldsException(missingFields);
139	        }
140	        LocalDate suppliedOrDefaultDate = ownerFieldsDto.getRegistrationDate() != null
141	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
142	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
143	        requireDailyLimitNotReached(registrationDate);
144	        requireCityBelowCapacity(ownerFieldsDto.getCity());
145	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
146	        requireUniqueTelephone(normalizedTelephone);
147	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
148	        if (!sharesHousehold) {
149	            requireUniqueHousehold(ownerFieldsDto.getLastName(), normalizedAddress);
150	        }
151	        ownerFieldsDto.setTelephone(normalizedTelephone);
152	        if (ownerFieldsDto.getEmail() != null) {
153	            ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
154	        }
155	        HttpHeaders headers = new HttpHeaders();
156	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
157	        owner.setAddress(normalizedAddress);
158	        owner.setRegistrationDate(registrationDate);
159	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
160	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
161	        if (sharesHousehold) {
162	            owner.setHouseholdId(joinHousehold(owner.getLastName(), owner.getAddress()));
163	        }
164	        this.clinicService.saveOwner(owner);
165	        AUDIT.info("Owner created id={} customerCode={} registrationDate={}",
166	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
167	        OwnerDto ownerDto = toOwnerDtoWithBulkWarning(owner);
168	        headers.setLocation(UriComponentsBuilder.newInstance()
