266	    /**
267	     * Builds the owner's customer code as {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the
268	     * upper-cased first three letters of {@code city}, {@code LAST3} the upper-cased first three letters
269	     * of {@code lastName}, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more
270	     * than the number of owners already in that city (e.g. {@code SYD-SMI-0007}).
271	     *
272	     * @param city the owner's city (already validated non-blank)
273	     * @param lastName the owner's last name (already validated non-blank)
274	     * @return the formatted customer code for the owner being created
275	     */
276	    private String nextCustomerCode(String city, String lastName) {
277	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
278	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
279	        int sequence = (int) this.clinicService.findAllOwners().stream()
280	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
281	            .count() + 1;
282	        return String.format("%s-%s-%04d", city3, last3, sequence);
283	    }
