311	    /**
312	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
313	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
314	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
315	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
316	     * {@code "+61412345678"}.
317	     *
318	     * @param telephone the raw telephone value from the request
319	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
320	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
321	     */
322	    private static String normalizeTelephone(String telephone) {
323	        String e164 = toE164(telephone);
324	        if (e164 == null) {
325	            throw new InvalidFieldValueException("telephone",
326	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
327	        }
328	        return e164;
329	    }
330	
331	    /**
332	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
333	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
334	     * owners' stored numbers when detecting duplicates.
335	     */
336	    private static String toE164(String telephone) {
337	        if (telephone == null) {
338	            return null;
339	        }
340	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
341	        String digits;
342	        if (cleaned.startsWith("+")) {
343	            digits = cleaned.substring(1);
344	        } else {
345	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
346	            digits = "61" + national;
347	        }
348	        if (!digits.matches("[0-9]{8,15}")) {
349	            return null;
350	        }
351	        return "+" + digits;
352	    }
