354	    /**
355	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
356	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
357	     *
358	     * @param email the raw email value from the request (already known to be non-null)
359	     * @return the lower-cased email to be stored and returned
360	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
361	     */
362	    private static String normalizeEmail(String email) {
363	        String trimmed = email.trim();
364	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
365	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
366	        }
367	        return trimmed.toLowerCase(Locale.ROOT);
368	    }
