370	    /** The maximum number of owners permitted in a single city; the {@code (50 + 1)}th is rejected. */
371	    private static final int MAX_OWNERS_PER_CITY = 50;
372	
373	    /**
374	     * Rejects the request when the owner's city already contains {@link #MAX_OWNERS_PER_CITY} or more
375	     * owners, comparing city names case-insensitively (consistent with the per-city customer-code
376	     * sequence). Callers reach this only once {@code city} has been validated non-blank.
377	     *
378	     * @param city the incoming owner's city (already validated non-blank)
379	     * @throws CityAtCapacityException if the city is already at or above its owner capacity
380	     */
381	    /** The maximum number of owners that may be registered in a single day; the {@code (100 + 1)}th is rejected. */
382	    private static final int MAX_OWNERS_PER_DAY = 100;
383	
384	    /**
385	     * Rejects the request when {@link #MAX_OWNERS_PER_DAY} or more owners have already been registered
386	     * on {@code businessDay}, counting existing owners whose {@code registrationDate} equals that date.
387	     * New owners take {@code businessDay} as their {@code registrationDate} (the supplied or defaulted
388	     * date rolled forward to a business day), so this caps the number that may be created per day.
389	     *
390	     * @param businessDay the adjusted business-day registration date of the owner being created
391	     * @throws DailyOwnerLimitException if the daily owner-creation limit has already been reached
392	     */
393	    /**
394	     * The number of owners for a single day beyond which the {@code bulkSignupWarning} flag is
395	     * raised; the warning is true once <em>more than</em> this many owners share a registration date.
396	     */
397	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
398	
399	    /**
400	     * Maps {@code owner} to its DTO and sets the {@code bulkSignupWarning} flag: {@code true} when
401	     * more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for this
402	     * owner's registration date, otherwise {@code false}.
403	     *
404	     * @param owner the owner to map
405	     * @return the owner DTO with its bulk-signup warning flag populated
406	     */
407	    private OwnerDto toOwnerDtoWithBulkWarning(Owner owner) {
408	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
409	        ownerDto.setBulkSignupWarning(exceedsBulkSignupThreshold(owner.getRegistrationDate()));
410	        return ownerDto;
411	    }
412	
413	    /**
414	     * Returns whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
415	     * created on {@code registrationDate}, counting existing owners whose {@code registrationDate}
416	     * equals that date. Returns {@code false} when {@code registrationDate} is {@code null}.
417	     */
418	    private boolean exceedsBulkSignupThreshold(LocalDate registrationDate) {
419	        if (registrationDate == null) {
420	            return false;
421	        }
422	        long registeredThatDay = this.clinicService.findAllOwners().stream()
423	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
424	            .count();
425	        return registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
426	    }
