428	    private void requireDailyLimitNotReached(LocalDate businessDay) {
429	        long registeredThatDay = this.clinicService.findAllOwners().stream()
430	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
431	            .count();
432	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
433	            throw new DailyOwnerLimitException(MAX_OWNERS_PER_DAY);
434	        }
435	    }
436	
437	    /**
438	     * Rolls {@code date} forward to a business day: when it falls on a Saturday or Sunday it advances
439	     * to the following Monday; a weekday is returned unchanged. Applied to the effective registration
440	     * date (whether supplied in the request or defaulted to the server date) so a weekend registration
441	     * is recorded on the next business day, and every value derived from the registration date uses the
442	     * adjusted date.
443	     *
444	     * @param date the effective registration date (supplied or defaulted), never {@code null}
445	     * @return the same date, or the next Monday when {@code date} is a weekend
446	     */
447	    private static LocalDate toBusinessDay(LocalDate date) {
448	        DayOfWeek day = date.getDayOfWeek();
449	        if (day == DayOfWeek.SATURDAY) {
450	            return date.plusDays(2);
451	        }
452	        if (day == DayOfWeek.SUNDAY) {
453	            return date.plusDays(1);
454	        }
455	        return date;
456	    }
