468	     * Rejects the request when {@code normalizedTelephone} is already used by any existing owner,
469	     * comparing on the E.164 form so differently-formatted stored numbers still collide.
470	     *
471	     * @param normalizedTelephone the incoming owner's normalized E.164 telephone
472	     * @throws DuplicateTelephoneException if another owner already uses this telephone
473	     */
474	    private void requireUniqueTelephone(String normalizedTelephone) {
475	        boolean taken = this.clinicService.findAllOwners().stream()
476	            .map(Owner::getTelephone)
477	            .map(OwnerRestControllerV1::toE164)
478	            .filter(existing -> existing != null)
479	            .anyMatch(normalizedTelephone::equals);
